1	// In-process, time bounded lease registry with append-only log persistence.
2	// Time only moves when the injected clock moves; nothing expires on its own.
3	// Tokens are derived from the injected clock as well, never from wall time.
4	
5	import fs from 'node:fs';
6	
7	const LOG_VERSION = 1;
8	
9	export class LeaseTakenError extends Error {
10	  constructor(resource, holder) {
11	    super(`lease for resource ${String(resource)} is already held`);
12	    this.name = 'LeaseTakenError';
13	    this.code = LeaseTakenError.code;
14	    this.resource = resource;
15	    this.holder = holder ?? null;
16	  }
17	}
18	LeaseTakenError.code = 'LEASE_TAKEN';
19	
20	export class LogFileError extends Error {
21	  constructor(message, cause) {
22	    super(message);
23	    this.name = 'LogFileError';
24	    this.code = LogFileError.code;
25	    this.cause = cause ?? null;
26	  }
27	}
28	LogFileError.code = 'LOG_FILE_ERROR';
29	
30	// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
31	// has a node in the queue; renewals push a fresh node and retire the old one,
32	// so reclaiming expired leases only walks entries that are actually due
33	// instead of scanning the whole table.
34	class ExpiryQueue {
35	  constructor() {
36	    this.nodes = [];
37	  }
38	
39	  get size() {
40	    return this.nodes.length;
41	  }
42	
43	  push(node) {
44	    const nodes = this.nodes;
45	    nodes.push(node);
46	    let i = nodes.length - 1;
47	    while (i > 0) {
48	      const parent = (i - 1) >> 1;
49	      if (expiresBefore(nodes[i], nodes[parent])) {
50	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
51	        i = parent;
52	      } else {
53	        break;
54	      }
55	    }
56	  }
57	
58	  peek() {
59	    return this.nodes[0];
60	  }
61	
62	  pop() {
63	    const nodes = this.nodes;
64	    const top = nodes[0];
65	    const last = nodes.pop();
66	    if (nodes.length > 0) {
67	      nodes[0] = last;
68	      let i = 0;
69	      for (;;) {
70	        const left = i * 2 + 1;
71	        const right = left + 1;
72	        let next = i;
73	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
74	          next = left;
75	        }
76	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
77	          next = right;
78	        }
79	        if (next === i) {
80	          break;
81	        }
82	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
83	        i = next;
84	      }
85	    }
86	    return top;
87	  }
88	}
89	
90	function expiresBefore(a, b) {
91	  if (a.expiresAt !== b.expiresAt) {
92	    return a.expiresAt < b.expiresAt;
93	  }
94	  return a.order < b.order;
95	}
96	
97	let registrySequence = 0;
98	
99	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
100	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
101	    throw new TypeError('ttlMs must be a positive finite number');
102	  }
103	  if (typeof clock !== 'function') {
104	    throw new TypeError('clock must be a function');
105	  }
106	
107	  const defaultTtlMs = ttlMs;
108	  // resource -> FIFO array of waiter records; waitId -> waiter (pending only).
109	  // Waiters live in memory only: queueing, timing out and cancelling are not
110	  // logged, only the eventual grant is.
111	  const waitQueues = new Map();
112	  const pendingWaiters = new Map();
113	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
114	  const leases = new Map();
115	  // Every token this instance knows about, including replayed credentials
116	  // that were already released or reclaimed, so a freshly minted token can
117	  // never reuse a dead credential's string.
118	  const knownTokens = new Set();
119	  // resource -> token of the lease currently occupying it
120	  const occupied = new Map();
121	  const expiryQueue = new ExpiryQueue();
122	
123	  const counters = {
124	    granted: 0,
125	    renewed: 0,
126	    released: 0,
127	    reclaimed: 0,
128	  };
129	
130	  // Per-instance identity makes tokens unique across registries living in the
131	  // same process; one instance can never present a token another owns.
132	  registrySequence += 1;
133	  const registryId = registrySequence;
134	  let tokenSequence = 0;
135	  let queueOrder = 0;
136	  let waitSequence = 0;
137	
138	  function mintToken(now, seq = tokenSequence) {
139	    // Pure candidate: nothing is committed until the event is on disk, so a
140	    // failed append rolls all the way back. Pids and instance ids can coincide
141	    // after a restart, so skip any sequence that collides with a credential
142	    // reconstructed from the log. The caller threads the sequence through when
143	    // it mints several tokens for one atomic write.
144	    let token;
145	    do {
146	      seq += 1;
147	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
148	    } while (knownTokens.has(token));
149	    return { token, seq };
150	  }
151	
152	  function enqueue(token, lease) {
153	    expiryQueue.push({
154	      token,
155	      expiresAt: lease.expiresAt,
156	      heapSeq: lease.heapSeq,
157	      order: queueOrder++,
158	    });
159	  }
160	
161	  function isLive(lease, now) {
162	    return lease !== undefined && lease.expiresAt > now;
163	  }
164	
165	  function appendEvents(events) {
166	    if (logPath === null) {
167	      return;
168	    }
169	    // One write for the whole batch: an operation that frees a resource and
170	    // wakes a waiter either lands completely or not at all.
171	    let text = '';
172	    for (const event of events) {
173	      text += `${JSON.stringify(event)}\n`;
174	    }
175	    try {
176	      fs.appendFileSync(logPath, text);
177	    } catch (cause) {
178	      throw new LogFileError(
179	        `failed to append to lease log at ${logPath}`,
180	        cause,
181	      );
182	    }
183	  }
184	
185	  function appendEvent(event) {
186	    appendEvents([event]);
187	  }
188	
189	  // A queued request gives up once the clock reaches its deadline and is
190	  // never woken afterwards. Dropping it moves no counter and no ownership.
191	  function purgeExpiredWaiters(now) {
192	    for (const [resource, queue] of waitQueues) {
193	      for (let i = queue.length - 1; i >= 0; i -= 1) {
194	        const waiter = queue[i];
195	        if (waiter.deadline <= now) {
196	          queue.splice(i, 1);
197	          pendingWaiters.delete(waiter.waitId);
198	          waiter.ticket.status = 'expired';
199	        }
200	      }
201	      if (queue.length === 0) {
202	        waitQueues.delete(resource);
203	      }
204	    }
205	  }
206	
207	  function enqueueWaiter(resource, holder, ttlMs, now, waitMs) {
208	    waitSequence += 1;
209	    const waitId = `wait-${registryId}-${waitSequence}`;
210	    // The ticket is the caller's handle: it starts as a waiting result and is
211	    // updated in place when the request is granted, expires or is cancelled.
212	    const ticket = { status: 'waiting', resource, holder, waitId };
213	    const waiter = {
214	      waitId,
215	      resource,
216	      holder,
217	      ttlMs,
218	      deadline: now + waitMs,
219	      ticket,
220	    };
221	    let queue = waitQueues.get(resource);
222	    if (queue === undefined) {
223	      queue = [];
224	      waitQueues.set(resource, queue);
225	    }
226	    queue.push(waiter);
227	    pendingWaiters.set(waitId, waiter);
228	    return ticket;
229	  }
230	
231	  // Plan the grant to the head of the resource's queue without touching any
232	  // state; the caller commits only after the events are safely on disk.
233	  function planWakeup(resource, now, seq) {
234	    const queue = waitQueues.get(resource);
235	    if (queue === undefined || queue.length === 0) {
236	      return null;
237	    }
238	    const waiter = queue[0];
239	    const minted = mintToken(now, seq);
240	    const expiresAt = now + waiter.ttlMs;
241	    return {
242	      waiter,
243	      token: minted.token,
244	      seq: minted.seq,
245	      expiresAt,
246	      event: {
247	        v: LOG_VERSION,
248	        type: 'acquire',
249	        at: now,
250	        token: minted.token,
251	        resource,
252	        holder: waiter.holder,
253	        ttlMs: waiter.ttlMs,
254	        expiresAt,
255	        waitId: waiter.waitId,
256	      },
257	    };
258	  }
259	
260	  function applyWakeup(wake) {
261	    const { waiter } = wake;
262	    tokenSequence = wake.seq;
263	    knownTokens.add(wake.token);
264	    const lease = {
265	      resource: waiter.resource,
266	      holder: waiter.holder,
267	      expiresAt: wake.expiresAt,
268	      ttlMs: waiter.ttlMs,
269	      legacy: false,
270	      heapSeq: 0,
271	    };
272	    leases.set(wake.token, lease);
273	    occupied.set(waiter.resource, wake.token);
274	    enqueue(wake.token, lease);
275	    counters.granted += 1;
276	
277	    const queue = waitQueues.get(waiter.resource);
278	    queue.shift();
279	    if (queue.length === 0) {
280	      waitQueues.delete(waiter.resource);
281	    }
282	    pendingWaiters.delete(waiter.waitId);
283	    waiter.ticket.status = 'granted';
284	    waiter.ticket.token = wake.token;
285	    waiter.ticket.expiresAt = wake.expiresAt;
286	  }
287	
288	  function acquire(resource, holder, ttlMs = defaultTtlMs, waitMs = undefined) {
289	    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
290	      throw new TypeError('ttlMs must be a positive finite number');
291	    }
292	    const wantsWait = waitMs !== undefined && waitMs !== null;
293	    if (wantsWait && (!Number.isFinite(waitMs) || waitMs <= 0)) {
294	      throw new TypeError('waitMs must be a positive finite number');
295	    }
296	    const now = clock();
297	    purgeExpiredWaiters(now);
298	    const currentToken = occupied.get(resource);
299	    if (currentToken !== undefined) {
300	      const current = leases.get(currentToken);
301	      if (isLive(current, now)) {
302	        if (!wantsWait) {
303	          throw new LeaseTakenError(resource, current.holder);
304	        }
305	        // Occupied: take a place in line instead of throwing. The resource
306	        // does not change hands just because a waiter showed up.
307	        return enqueueWaiter(resource, holder, ttlMs, now, waitMs);
308	      }
309	      // Expired but not yet swept: the resource is free. The stale record is
310	      // dropped together with the new grant below (no event of its own).
311	    }
312	
313	    if (waitQueues.has(resource)) {
314	      // Queued waiters hold their place in line: a late acquire cannot take
315	      // the resource they are waiting for, it can only join the queue.
316	      if (!wantsWait) {
317	        const stale = currentToken !== undefined
318	          ? leases.get(currentToken)
319	          : undefined;
320	        throw new LeaseTakenError(resource, stale?.holder ?? null);
321	      }
322	      return enqueueWaiter(resource, holder, ttlMs, now, waitMs);
323	    }
324	
325	    const { token, seq } = mintToken(now);
326	    const expiresAt = now + ttlMs;
327	    // Persist before touching any state: a failed write leaves the registry
328	    // exactly as it was before the call.
329	    appendEvent({
330	      v: LOG_VERSION,
331	      type: 'acquire',
332	      at: now,
333	      token,
334	      resource,
335	      holder,
336	      ttlMs,
337	      expiresAt,
338	    });
339	
340	    tokenSequence = seq;
341	    knownTokens.add(token);
342	    if (currentToken !== undefined) {
343	      occupied.delete(resource);
344	      leases.delete(currentToken);
345	    }
346	    const lease = {
347	      resource,
348	      holder,
349	      expiresAt,
350	      ttlMs,
351	      legacy: false,
352	      heapSeq: 0,
353	    };
354	    leases.set(token, lease);
355	    occupied.set(resource, token);
356	    enqueue(token, lease);
357	    counters.granted += 1;
358	
359	    return { resource, holder, token, expiresAt };
360	  }
361	
362	  function renew(token) {
363	    const lease = leases.get(token);
364	    if (lease === undefined || lease.legacy) {
365	      return false;
366	    }
367	    const now = clock();
368	    if (lease.expiresAt <= now) {
369	      return false;
370	    }
371	    purgeExpiredWaiters(now);
372	    const expiresAt = now + lease.ttlMs;
373	    appendEvent({ v: LOG_VERSION, type: 'renew', at: now, token, expiresAt });
374	
375	    lease.expiresAt = expiresAt;
376	    lease.heapSeq += 1;
377	    enqueue(token, lease);
378	    counters.renewed += 1;
379	    return true;
380	  }
381	
382	  function release(token) {
383	    const lease = leases.get(token);
384	    if (lease === undefined || lease.legacy) {
385	      return false;
386	    }
387	    const now = clock();
388	    if (lease.expiresAt <= now) {
389	      return false;
390	    }
391	    purgeExpiredWaiters(now);
392	
393	    // A freed resource goes straight to the head of its queue. The wakeup
394	    // grant is planned first and appended in the same write as the release,
395	    // so a failed log leaves both the lease and the queue untouched.
396	    const wake = planWakeup(lease.resource, now, tokenSequence);
397	    const events = [{ v: LOG_VERSION, type: 'release', at: now, token }];
398	    if (wake !== null) {
399	      events.push(wake.event);
400	    }
401	    appendEvents(events);
402	
403	    // The record comes off immediately; its queued node retires lazily.
404	    leases.delete(token);
405	    if (occupied.get(lease.resource) === token) {
406	      occupied.delete(lease.resource);
407	    }
408	    counters.released += 1;
409	    if (wake !== null) {
410	      applyWakeup(wake);
411	    }
412	    return true;
413	  }
414	
415	  // Cancelling only lands on a request that is still queued: an already
416	  // woken, expired or cancelled request reports false, as does an unknown id.
417	  function cancel(waitId) {
418	    purgeExpiredWaiters(clock());
419	    const waiter = pendingWaiters.get(waitId);
420	    if (waiter === undefined) {
421	      return false;
422	    }
423	    const queue = waitQueues.get(waiter.resource);
424	    queue.splice(queue.indexOf(waiter), 1);
425	    if (queue.length === 0) {
426	      waitQueues.delete(waiter.resource);
427	    }
428	    pendingWaiters.delete(waiter.waitId);
429	    waiter.ticket.status = 'cancelled';
430	    return true;
431	  }
432	
433	  function sweep(now = clock()) {
434	    purgeExpiredWaiters(now);
435	    const due = [];
436	    while (expiryQueue.size > 0) {
437	      const node = expiryQueue.peek();
438	      if (node.expiresAt > now) {
439	        break;
440	      }
441	      expiryQueue.pop();
442	      const lease = leases.get(node.token);
443	      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
444	        // Retired node: release, retake or renewal already superseded it.
445	        continue;
446	      }
447	      due.push(node);
448	    }
449	
450	    if (due.length === 0) {
451	      return [];
452	    }
453	
454	    // Reclaimed resources are handed to the head of their queue in the same
455	    // expiry order the reclaim happens; every wakeup grant rides along in the
456	    // same log write, so a failed append rolls everything back together.
457	    const events = [{
458	      v: LOG_VERSION,
459	      type: 'reclaim',
460	      at: now,
461	      items: due.map((node) => ({
462	        token: node.token,
463	        resource: leases.get(node.token).resource,
464	      })),
465	    }];
466	    const wakes = [];
467	    let seqCursor = tokenSequence;
468	    for (const node of due) {
469	      const lease = leases.get(node.token);
470	      if (occupied.get(lease.resource) !== node.token) {
471	        continue;
472	      }
473	      const wake = planWakeup(lease.resource, now, seqCursor);
474	      if (wake !== null) {
475	        seqCursor = wake.seq;
476	        wakes.push(wake);
477	        events.push(wake.event);
478	      }
479	    }
480	
481	    try {
482	      appendEvents(events);
483	    } catch (error) {
484	      // The write never happened: put the popped nodes back so the queue is
485	      // byte-for-byte the same as before the call.
486	      for (const node of due) {
487	        expiryQueue.push(node);
488	      }
489	      throw error;
490	    }
491	
492	    const freed = [];
493	    for (const node of due) {
494	      const lease = leases.get(node.token);
495	      leases.delete(node.token);
496	      if (occupied.get(lease.resource) === node.token) {
497	        occupied.delete(lease.resource);
498	        counters.reclaimed += 1;
499	        freed.push(lease.resource);
500	      }
501	    }
502	    for (const wake of wakes) {
503	      applyWakeup(wake);
504	    }
505	    return freed;
506	  }
507	
508	  function holder(resource) {
509	    const now = clock();
510	    purgeExpiredWaiters(now);
511	    const token = occupied.get(resource);
512	    if (token === undefined) {
513	      return null;
514	    }
515	    const lease = leases.get(token);
516	    if (!isLive(lease, now)) {
517	      return null;
518	    }
519	    return lease.holder;
520	  }
521	
522	  function stats() {
523	    let live = 0;
524	    const now = clock();
525	    purgeExpiredWaiters(now);
526	    for (const token of occupied.values()) {
527	      const lease = leases.get(token);
528	      if (isLive(lease, now)) {
529	        live += 1;
530	      }
531	    }
532	    return {
533	      granted: counters.granted,
534	      renewed: counters.renewed,
535	      released: counters.released,
536	      reclaimed: counters.reclaimed,
537	      live,
538	    };
539	  }
540	
541	  replay();
542	
543	  return { acquire, renew, release, sweep, holder, stats, cancel };
544	
545	  function replay() {
546	    if (logPath === null) {
547	      return;
548	    }
549	
550	    let text;
551	    try {
552	      text = fs.readFileSync(logPath, 'utf8');
553	    } catch (cause) {
554	      if (cause.code === 'ENOENT') {
555	        // No log yet: start from an empty registry.
556	        return;
557	      }
558	      throw new LogFileError(
559	        `failed to read lease log at ${logPath}`,
560	        cause,
561	      );
562	    }
563	
564	    const lines = text.split('\n');
565	    for (let i = 0; i < lines.length; i += 1) {
566	      const line = lines[i];
567	      if (line.trim() === '') {
568	        continue;
569	      }
570	      let event;
571	      try {
572	        event = JSON.parse(line);
573	      } catch (cause) {
574	        throw new LogFileError(
575	          `corrupt lease log entry on line ${i + 1} of ${logPath}`,
576	          cause,
577	        );
578	      }
579	      replayEvent(event, i + 1);
580	    }
581	  }
582	
583	  function replayEvent(event, lineNumber) {
584	    if (event === null || typeof event !== 'object' || event.v !== LOG_VERSION) {
585	      throw new LogFileError(
586	        `unrecognized lease log version on line ${lineNumber} of ${logPath}`,
587	      );
588	    }
589	
590	    switch (event.type) {
591	      case 'acquire': {
592	        if (
593	          typeof event.token !== 'string' ||
594	          !Number.isFinite(event.ttlMs) ||
595	          !Number.isFinite(event.expiresAt)
596	        ) {
597	          throw new LogFileError(
598	            `corrupt acquire entry on line ${lineNumber} of ${logPath}`,
599	          );
600	        }
601	        const previousToken = occupied.get(event.resource);
602	        if (previousToken !== undefined && previousToken !== event.token) {
603	          // A later grant retook an expired, unswept resource.
604	          leases.delete(previousToken);
605	        }
606	        const lease = {
607	          resource: event.resource,
608	          holder: event.holder,
609	          expiresAt: event.expiresAt,
610	          ttlMs: event.ttlMs,
611	          // Credentials issued before this process started are void: the
612	          // lease keeps occupying the resource, but its token cannot
613	          // renew or release it.
614	          legacy: true,
615	          heapSeq: 0,
616	        };
617	        leases.set(event.token, lease);
618	        occupied.set(event.resource, event.token);
619	        knownTokens.add(event.token);
620	        enqueue(event.token, lease);
621	        counters.granted += 1;
622	        break;
623	      }
624	      case 'renew': {
625	        const lease = leases.get(event.token);
626	        if (
627	          typeof event.token !== 'string' ||
628	          !Number.isFinite(event.expiresAt)
629	        ) {
630	          throw new LogFileError(
631	            `corrupt renew entry on line ${lineNumber} of ${logPath}`,
632	          );
633	        }
634	        if (lease !== undefined) {
635	          lease.expiresAt = event.expiresAt;
636	          lease.heapSeq += 1;
637	          enqueue(event.token, lease);
638	        }
639	        counters.renewed += 1;
640	        break;
641	      }
642	      case 'release': {
643	        if (typeof event.token !== 'string') {
644	          throw new LogFileError(
645	            `corrupt release entry on line ${lineNumber} of ${logPath}`,
646	          );
647	        }
648	        const lease = leases.get(event.token);
649	        if (lease !== undefined) {
650	          leases.delete(event.token);
651	          if (occupied.get(lease.resource) === event.token) {
652	            occupied.delete(lease.resource);
653	          }
654	        }
655	        counters.released += 1;
656	        break;
657	      }
658	      case 'reclaim': {
659	        if (!Array.isArray(event.items)) {
660	          throw new LogFileError(
661	            `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
662	          );
663	        }
664	        for (const item of event.items) {
665	          if (item === null || typeof item !== 'object' ||
666	              typeof item.token !== 'string') {
667	            throw new LogFileError(
668	              `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
669	            );
670	          }
671	          const token = item.token;
672	          const lease = leases.get(token);
673	          if (lease !== undefined) {
674	            leases.delete(token);
675	            if (occupied.get(lease.resource) === token) {
676	              occupied.delete(lease.resource);
677	            }
678	          }
679	          counters.reclaimed += 1;
680	        }
681	        break;
682	      }
683	      default: {
684	        throw new LogFileError(
685	          `unknown lease log event type on line ${lineNumber} of ${logPath}`,
686	        );
687	      }
688	    }
689	  }
690	}
691

