1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	
4	import { createRegistry, LeaseTakenError } from '../src/index.js';
5	
6	function fakeClock(start = 0) {
7	  let now = start;
8	  const clock = () => now;
9	  clock.set = (value) => {
10	    now = value;
11	  };
12	  clock.advance = (delta) => {
13	    now += delta;
14	  };
15	  return clock;
16	}
17	
18	test('acquire returns a credential with an absolute expiry', () => {
19	  const clock = fakeClock(1000);
20	  const registry = createRegistry({ ttlMs: 50, clock });
21	
22	  const lease = registry.acquire('db', 'node-1', 30);
23	
24	  assert.deepEqual(
25	    { resource: lease.resource, holder: lease.holder, expiresAt: lease.expiresAt },
26	    { resource: 'db', holder: 'node-1', expiresAt: 1030 },
27	  );
28	  assert.equal(typeof lease.token, 'string');
29	  assert.deepEqual(registry.stats(), {
30	    granted: 1,
31	    renewed: 0,
32	    released: 0,
33	    reclaimed: 0,
34	    live: 1,
35	  });
36	});
37	
38	test('acquire falls back to the registry default ttl', () => {
39	  const clock = fakeClock(0);
40	  const registry = createRegistry({ ttlMs: 25, clock });
41	
42	  const lease = registry.acquire('r', 'h');
43	  assert.equal(lease.expiresAt, 25);
44	});
45	
46	test('acquire on a live resource throws LeaseTakenError with a code', () => {
47	  const clock = fakeClock(0);
48	  const registry = createRegistry({ ttlMs: 50, clock });
49	  registry.acquire('r', 'a');
50	
51	  let caught;
52	  assert.throws(
53	    () => registry.acquire('r', 'b'),
54	    (error) => {
55	      caught = error;
56	      return error instanceof LeaseTakenError;
57	    },
58	  );
59	  assert.equal(caught.code, 'LEASE_TAKEN');
60	  assert.equal(caught.resource, 'r');
61	
62	  // Failed acquire changes nothing.
63	  assert.equal(registry.holder('r'), 'a');
64	  assert.equal(registry.stats().granted, 1);
65	});
66	
67	test('time does not advance on its own', () => {
68	  const clock = fakeClock(0);
69	  const registry = createRegistry({ ttlMs: 10, clock });
70	  registry.acquire('r', 'a');
71	
72	  assert.equal(registry.holder('r'), 'a');
73	  assert.equal(registry.stats().live, 1);
74	});
75	
76	test('renew extends a live lease from the current clock reading', () => {
77	  const clock = fakeClock(0);
78	  const registry = createRegistry({ ttlMs: 100, clock });
79	  const lease = registry.acquire('r', 'a', 40);
80	  assert.equal(lease.expiresAt, 40);
81	
82	  clock.set(30);
83	  assert.equal(registry.renew(lease.token), true);
84	  assert.equal(registry.stats().renewed, 1);
85	
86	  clock.set(60);
87	  assert.equal(registry.holder('r'), 'a');
88	  clock.set(71);
89	  assert.equal(registry.holder('r'), null);
90	});
91	
92	test('renew after expiry returns false and changes nothing', () => {
93	  const clock = fakeClock(0);
94	  const registry = createRegistry({ ttlMs: 10, clock });
95	  const lease = registry.acquire('r', 'a');
96	
97	  clock.set(10); // expiresAt <= now means expired
98	  assert.equal(registry.renew(lease.token), false);
99	  assert.equal(registry.stats().renewed, 0);
100	  assert.equal(registry.stats().granted, 1);
101	});
102	
103	test('operations on unknown, released and swept tokens return false', () => {
104	  const clock = fakeClock(0);
105	  const registry = createRegistry({ ttlMs: 10, clock });
106	  const lease = registry.acquire('r', 'a');
107	
108	  assert.equal(registry.renew('does-not-exist'), false);
109	  assert.equal(registry.release('does-not-exist'), false);
110	
111	  assert.equal(registry.release(lease.token), true);
112	  assert.equal(registry.release(lease.token), false);
113	  assert.equal(registry.renew(lease.token), false);
114	  assert.deepEqual(registry.stats(), {
115	    granted: 1,
116	    renewed: 0,
117	    released: 1,
118	    reclaimed: 0,
119	    live: 0,
120	  });
121	
122	  clock.set(20);
123	  assert.deepEqual(registry.sweep(), []);
124	});
125	
126	test('release frees the resource immediately', () => {
127	  const clock = fakeClock(0);
