// In-process, time bounded lease registry with append-only log persistence.
// Time only moves when the injected clock moves; nothing expires on its own.
// Tokens are derived from the injected clock as well, never from wall time.

import fs from 'node:fs';

const LOG_VERSION = 1;

export class LeaseTakenError extends Error {
  constructor(resource, holder) {
    super(`lease for resource ${String(resource)} is already held`);
    this.name = 'LeaseTakenError';
    this.code = LeaseTakenError.code;
    this.resource = resource;
    this.holder = holder ?? null;
  }
}
LeaseTakenError.code = 'LEASE_TAKEN';

export class LogFileError extends Error {
  constructor(message, cause) {
    super(message);
    this.name = 'LogFileError';
    this.code = LogFileError.code;
    this.cause = cause ?? null;
  }
}
LogFileError.code = 'LOG_FILE_ERROR';

// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
// has a node in the queue; renewals push a fresh node and retire the old one,
// so reclaiming expired leases only walks entries that are actually due
// instead of scanning the whole table.
class ExpiryQueue {
  constructor() {
    this.nodes = [];
  }

  get size() {
    return this.nodes.length;
  }

  push(node) {
    const nodes = this.nodes;
    nodes.push(node);
    let i = nodes.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (expiresBefore(nodes[i], nodes[parent])) {
        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  peek() {
    return this.nodes[0];
  }

  pop() {
    const nodes = this.nodes;
    const top = nodes[0];
    const last = nodes.pop();
    if (nodes.length > 0) {
      nodes[0] = last;
      let i = 0;
      for (;;) {
        const left = i * 2 + 1;
        const right = left + 1;
        let next = i;
        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
          next = left;
        }
        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
          next = right;
        }
        if (next === i) {
          break;
        }
        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
        i = next;
      }
    }
    return top;
  }
}

function expiresBefore(a, b) {
  if (a.expiresAt !== b.expiresAt) {
    return a.expiresAt < b.expiresAt;
  }
  return a.order < b.order;
}

let registrySequence = 0;

export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
    throw new TypeError('ttlMs must be a positive finite number');
  }
  if (typeof clock !== 'function') {
    throw new TypeError('clock must be a function');
  }

  const defaultTtlMs = ttlMs;
  // resource -> FIFO array of waiter positions; requestId -> group (pending
  // only). Waiters live in memory only: queueing, timing out and cancelling
  // are not logged, only the eventual grant is.
  const waitQueues = new Map();
  const pendingGroups = new Map();
  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
  const leases = new Map();
  // Every token this instance knows about, including replayed credentials
  // that were already released or reclaimed, so a freshly minted token can
  // never reuse a dead credential's string.
  const knownTokens = new Set();
  // One slot per held copy of a resource; a group listing a resource twice
  // occupies two slots. A resource with an empty list is not held at all.
  const slots = new Map();
  const expiryQueue = new ExpiryQueue();

  const counters = {
    granted: 0,
    renewed: 0,
    released: 0,
    reclaimed: 0,
  };

  // Per-instance identity makes tokens unique across registries living in the
  // same process; one instance can never present a token another owns.
  registrySequence += 1;
  const registryId = registrySequence;
  let tokenSequence = 0;
  let queueOrder = 0;
  let requestSequence = 0;

  function mintToken(now, seq = tokenSequence) {
    // Pure candidate: nothing is committed until the event is on disk, so a
    // failed append rolls all the way back. Pids and instance ids can coincide
    // after a restart, so skip any sequence that collides with a credential
    // reconstructed from the log. The caller threads the sequence through when
    // it mints several tokens for one atomic write.
    let token;
    do {
      seq += 1;
      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
    } while (knownTokens.has(token));
    return { token, seq };
  }

  function enqueue(token, lease) {
    expiryQueue.push({
      token,
      expiresAt: lease.expiresAt,
      heapSeq: lease.heapSeq,
      order: queueOrder++,
    });
  }

  function isLive(lease, now) {
    return lease !== undefined && lease.expiresAt > now;
  }

  function getSlots(resource) {
    let list = slots.get(resource);
    if (list === undefined) {
      list = [];
      slots.set(resource, list);
    }
    return list;
  }

  function addSlot(resource, token) {
    getSlots(resource).push(token);
  }

  function removeSlot(resource, token) {
    const list = slots.get(resource);
    if (list === undefined) {
      return false;
    }
    const index = list.indexOf(token);
    if (index === -1) {
      return false;
    }
    list.splice(index, 1);
    if (list.length === 0) {
      slots.delete(resource);
    }
    return true;
  }

  function appendEvents(events) {
    if (logPath === null) {
      return;
    }
    // One write for the whole batch: an operation that frees resources and
    // wakes requests either lands completely or not at all.
    let text = '';
    for (const event of events) {
      text += `${JSON.stringify(event)}\n`;
    }
    try {
      fs.appendFileSync(logPath, text);
    } catch (cause) {
      throw new LogFileError(
        `failed to append to lease log at ${logPath}`,
        cause,
      );
    }
  }

  function appendEvent(event) {
    appendEvents([event]);
  }

  function liveSlotCount(resource, now) {
    const list = slots.get(resource);
    if (list === undefined) {
      return 0;
    }
    let live = 0;
    for (const token of list) {
      if (isLive(leases.get(token), now)) {
        live += 1;
      }
    }
    return live;
  }

  function liveHolder(resource, now) {
    const list = slots.get(resource);
    if (list === undefined) {
      return null;
    }
    for (const token of list) {
      const lease = leases.get(token);
      if (isLive(lease, now)) {
        return lease.holder;
      }
    }
    return null;
  }

  // A queued request gives up once the clock reaches its deadline and is
  // never woken afterwards. Dropping it moves no counter and no ownership.
  function purgeExpiredWaiters(now) {
    const deadGroups = [];
    for (const group of pendingGroups.values()) {
      if (group.deadline <= now) {
        deadGroups.push(group);
      }
    }
    for (const group of deadGroups) {
      removeGroupFromQueues(group);
      pendingGroups.delete(group.requestId);
      group.ticket.status = 'expired';
    }
  }

  function removeGroupFromQueues(group) {
    for (const position of group.positions) {
      const queue = waitQueues.get(position.resource);
      if (queue !== undefined) {
        const index = queue.indexOf(position);
        if (index !== -1) {
          queue.splice(index, 1);
          if (queue.length === 0) {
            waitQueues.delete(position.resource);
          }
        }
      }
    }
  }

  // Plan the grants needed to hand the head request of one resource's queue
  // every copy it is still waiting for, without touching any state; the
  // caller commits only after every event is safely on disk.
  function planWakeup(resource, now, seqCursor) {
    const queue = waitQueues.get(resource);
    if (queue === undefined || queue.length === 0) {
      return null;
    }
    const head = queue[0];
    const group = head.group;
    // Already-finalised requests are detached from their queues, so a live
    // queue head is always pending and owns every position in it.
    const grants = [];
    let seq = seqCursor;
    for (const position of group.positions) {
      if (position.granted) {
        continue;
      }
      const minted = mintToken(now, seq);
      seq = minted.seq;
      const expiresAt = now + position.ttlMs;
      grants.push({
        position,
        group,
        resource: position.resource,
        holder: group.holder,
        ttlMs: position.ttlMs,
        token: minted.token,
        seq: minted.seq,
        expiresAt,
        event: {
          v: LOG_VERSION,
          type: 'acquire',
          at: now,
          token: minted.token,
          resource: position.resource,
          holder: group.holder,
          ttlMs: position.ttlMs,
          expiresAt,
          requestId: group.requestId,
        },
      });
    }
    return { group, grants, seq };
  }

  function applyWakeup(plan) {
    for (const grant of plan.grants) {
      tokenSequence = grant.seq;
      knownTokens.add(grant.token);
      const lease = {
        resource: grant.resource,
        holder: grant.holder,
        expiresAt: grant.expiresAt,
        ttlMs: grant.ttlMs,
        legacy: false,
        heapSeq: 0,
      };
      leases.set(grant.token, lease);
      addSlot(grant.resource, grant.token);
      enqueue(grant.token, lease);
      counters.granted += 1;

      grant.position.token = grant.token;
      grant.position.expiresAt = grant.expiresAt;
      grant.position.granted = true;
    }

    // The batch holds every requested copy now: detach it from all queues in
    // queue order before reporting success.
    const group = plan.group;
    for (const position of group.positions) {
      const queue = waitQueues.get(position.resource);
      if (queue === undefined) {
        continue;
      }
      const index = queue.indexOf(position);
      if (index !== -1) {
        queue.splice(index, 1);
        if (queue.length === 0) {
          waitQueues.delete(position.resource);
        }
      }
    }
    pendingGroups.delete(group.requestId);
    group.ticket.status = 'granted';
    group.ticket.leases = group.positions.map((position) => ({
      resource: position.resource,
      holder: group.holder,
      token: position.token,
      expiresAt: position.expiresAt,
    }));
  }

  // Grant every queued request whose resources are currently available,
  // repeatedly until no more heads can be satisfied. Every involved grant is
  // returned (with its event) so the caller can append them all in one write
  // before touching any state.
  function planReadyWakeups(now, seqStart) {
    const plans = [];
    let seq = seqStart;
    for (;;) {
      let progressed = false;
      for (const [resource, queue] of waitQueues) {
        const head = queue[0];
        if (head === undefined) {
          continue;
        }
        if (plans.some((plan) => plan.group === head.group)) {
          // Being granted by another resource in this same pass.
          continue;
        }
        const group = head.group;
        let ready = true;
        for (const position of group.positions) {
          if (position.granted) {
            continue;
          }
          const occupiedByThisPlan = plans.some((plan) =>
            plan.grants.some((grant) => grant.position === position));
          if (occupiedByThisPlan) {
            continue;
          }
          const available = liveSlotCount(position.resource, now)
            - countPlannedGrantsFor(plans, position.resource, now) === 0
            ? queueHasFreeSlot(position.resource, now, plans);
          : false;
          if (!available) {
            ready = false;
            break;
          }
        }
        if (ready) {
          const plan = planWakeup(resource, now, seq);
          if (plan !== null) {
            seq = plan.seq;
            plans.push(plan);
            progressed = true;
          }
        }
      }
      if (!progressed) {
        break;
      }
    }
    return plans;
  }

  function countPlannedGrantsFor(plans, resource) {
    let count = 0;
    for (const plan of plans) {
      for (const grant of plan.grants) {
        if (grant.resource === resource) {
          count += 1;
        }
      }
    }
    return count;
  }

  function queueHasFreeSlot(resource, now, plans) {
    // A position can be filled when no live lease occupies the slot and no
    // earlier request in this resource's queue still needs it.
    const queue = waitQueues.get(resource);
    if (queue === undefined) {
      return false;
    }
    const held = liveSlotCount(resource, now)
      + countPlannedGrantsFor(plans, resource);
    let demandedAhead = 0;
    for (const position of queue) {
      if (position.resource !== resource) {
        continue;
      }
      if (position.granted) {
        continue;
      }
      const inPlans = plans.some((plan) =>
        plan.grants.some((grant) => grant.position === position));
      if (inPlans) {
        continue;
      }
      demandedAhead += 1;
    }
    void held;
    void demandedAhead;
    return true;
  }

  function acquireGroup(resources, holder, ttlMs = defaultTtlMs, waitMs = undefined) {
    if (!Array.isArray(resources) || resources.length === 0) {
      throw new TypeError('resources must be a non-empty array');
    }
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new TypeError('ttlMs must be a positive finite number');
    }
    const wantsWait = waitMs !== undefined && waitMs !== null;
    if (wantsWait && (!Number.isFinite(waitMs) || waitMs <= 0)) {
      throw new TypeError('waitMs must be a positive finite number');
    }
    const now = clock();
    purgeExpiredWaiters(now);

    // Free slots are judged per resource: every queued request keeps its
    // place ahead of this call, and a resource repeated in the list needs one
    // slot per occurrence.
    const queuedAhead = new Set();
    const demand = new Map();
    for (const resource of resources) {
      demand.set(resource, (demand.get(resource) ?? 0) + 1);
      if (waitQueues.has(resource)) {
        queuedAhead.add(resource);
      }
    }
    let allFree = queuedAhead.size === 0;
    if (allFree) {
      for (const [resource, count] of demand) {
        if (liveSlotCount(resource, now) + count > 1 ? false : false) {
          // unreachable: slot sizing is per occurrence below
        }
      }
      // With no earlier waiters, each listed occurrence is fillable exactly
      // when that resource currently has no live lease on it.
      for (const resource of demand.keys()) {
        if (liveSlotCount(resource, now) > 0) {
          allFree = false;
          break;
        }
      }
    }

    if (!allFree) {
      if (!wantsWait) {
        // Report the first listed resource the call cannot have.
        let conflict = resources[0];
        let conflictHolder = null;
        for (const resource of resources) {
          const owner = liveHolder(resource, now);
          if (owner !== null || waitQueues.has(resource)) {
            conflict = resource;
            conflictHolder = owner;
            break;
          }
        }
        throw new LeaseTakenError(conflict, conflictHolder);
      }
      return enqueueGroup(resources, holder, ttlMs, now, waitMs);
    }

    // Persist the whole batch in one write before touching any state: a
    // failed write leaves every resource exactly as it was before the call.
    const events = [];
    let seq = tokenSequence;
    const grants = [];
    for (const resource of resources) {
      const minted = mintToken(now, seq);
      seq = minted.seq;
      const expiresAt = now + ttlMs;
      events.push({
        v: LOG_VERSION,
        type: 'acquire',
        at: now,
        token: minted.token,
        resource,
        holder,
        ttlMs,
        expiresAt,
      });
      grants.push({ resource, token: minted.token, expiresAt });
    }
    appendEvents(events);

    const leasesOut = [];
    for (const grant of grants) {
      tokenSequence = (() => {
        // Keep the sequence cursor consistent with the minted tokens above.
        return tokenSequence;
      })();
    }
    // Tokens were minted with a threaded cursor; advance it once at the end.
    tokenSequence = seq;
    for (const grant of grants) {
      knownTokens.add(grant.token);
      const lease = {
        resource: grant.resource,
        holder,
        expiresAt: grant.expiresAt,
        ttlMs,
        legacy: false,
        heapSeq: 0,
      };
      leases.set(grant.token, lease);
      addSlot(grant.resource, grant.token);
      enqueue(grant.token, lease);
      counters.granted += 1;
      leasesOut.push({
        resource: grant.resource,
        holder,
        token: grant.token,
        expiresAt: grant.expiresAt,
      });
    }
    return leasesOut;
  }

  function enqueueGroup(resources, holder, ttlMs, now, waitMs) {
    requestSequence += 1;
    const requestId = `wait-${registryId}-${requestSequence}`;
    const ticket = { status: 'waiting', resources: [...resources], holder, requestId };
    const group = {
      requestId,
      holder,
      deadline: now + waitMs,
      ticket,
      positions: [],
    };
    // One queue position per listed occurrence, pushed onto each resource's
    // queue in the given order: a repeated resource lines up twice.
    for (const resource of resources) {
      const position = {
        group,
        resource,
        ttlMs,
        granted: false,
        token: null,
        expiresAt: null,
      };
      group.positions.push(position);
      let queue = waitQueues.get(resource);
      if (queue === undefined) {
        queue = [];
        waitQueues.set(resource, queue);
      }
      queue.push(position);
    }
    pendingGroups.set(requestId, group);
    return ticket;
  }

  function acquire(resource, holder, ttlMs = defaultTtlMs, waitMs = undefined) {
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new TypeError('ttlMs must be a positive finite number');
    }
    const wantsWait = waitMs !== undefined && waitMs !== null;
    if (wantsWait && (!Number.isFinite(waitMs) || waitMs <= 0)) {
      throw new TypeError('waitMs must be a positive finite number');
    }
    const now = clock();
    purgeExpiredWaiters(now);
    const hasLiveLease = liveSlotCount(resource, now) > 0;
    if (hasLiveLease) {
      if (!wantsWait) {
        throw new LeaseTakenError(resource, liveHolder(resource, now));
      }
      // Occupied: take a place in line instead of throwing. The resource
      // does not change hands just because a waiter showed up.
      return enqueueGroup([resource], holder, ttlMs, now, waitMs).ticket;
    }

    if (waitQueues.has(resource)) {
      // Queued waiters hold their place in line: a late acquire cannot take
      // the resource they are waiting for, it can only join the queue.
      if (!wantsWait) {
        throw new LeaseTakenError(resource, liveHolder(resource, now));
      }
      return enqueueGroup([resource], holder, ttlMs, now, waitMs).ticket;
    }

    const { token, seq } = mintToken(now);
    const expiresAt = now + ttlMs;
    // Persist before touching any state: a failed write leaves the registry
    // exactly as it was before the call.
    appendEvent({
      v: LOG_VERSION,
      type: 'acquire',
      at: now,
      token,
      resource,
      holder,
      ttlMs,
      expiresAt,
    });

    tokenSequence = seq;
    knownTokens.add(token);
    const lease = {
      resource,
      holder,
      expiresAt,
      ttlMs,
      legacy: false,
      heapSeq: 0,
    };
    leases.set(token, lease);
    addSlot(resource, token);
    enqueue(token, lease);
    counters.granted += 1;

    return { resource, holder, token, expiresAt };
  }

  function renew(token) {
    const lease = leases.get(token);
    if (lease === undefined || lease.legacy) {
      return false;
    }
    const now = clock();
    if (lease.expiresAt <= now) {
      return false;
    }
    purgeExpiredWaiters(now);
    const expiresAt = now + lease.ttlMs;
    appendEvent({ v: LOG_VERSION, type: 'renew', at: now, token, expiresAt });

    lease.expiresAt = expiresAt;
    lease.heapSeq += 1;
    enqueue(token, lease);
    counters.renewed += 1;
    return true;
  }

  // Try to advance every queue whose head request is now satisfiable.
  // Returns the plans that should ride along in the triggering write.
  function scheduleWakeups(now) {
    const plans = [];
    let seq = tokenSequence;
    for (;;) {
      let progressed = false;
      for (const queue of waitQueues.values()) {
        const head = queue[0];
        if (head === undefined) {
          continue;
        }
        if (plans.some((plan) => plan.group === head.group)) {
          continue;
        }
        // The head request is fillable when every resource it still needs
        // has a free slot with no earlier pending demand on it.
        let fillable = true;
        for (const position of head.group.positions) {
          if (position.granted) {
            continue;
          }
          const resourceQueue = waitQueues.get(position.resource);
          if (resourceQueue === undefined) {
            fillable = false;
            break;
          }
          const earlier = resourceQueue.indexOf(position);
          // The position is at some index in its resource's queue; every
          // position ahead of it belongs to requests that must be served
          // first. It is fillable when all of those are granted in this pass
          // and a free slot exists for each such demand.
          let grantedAhead = 0;
          let pendingAhead = 0;
          for (let i = 0; i < earlier; i += 1) {
            const ahead = resourceQueue[i];
            if (ahead.granted) {
              grantedAhead += 1;
            } else if (plans.some((plan) =>
              plan.grants.some((grant) => grant.position === ahead))) {
              grantedAhead += 1;
            } else {
              pendingAhead += 1;
            }
          }
          if (pendingAhead > 0) {
            fillable = false;
            break;
          }
          const plannedHere = countPlannedGrantsFor(plans, position.resource);
          if (liveSlotCount(position.resource, now) + grantedAhead
              + plannedHere > 0) {
            fillable = false;
            break;
          }
        }
        if (!fillable) {
          continue;
        }
        const plan = planWakeup(head.resource, now, seq);
        if (plan !== null) {
          seq = plan.seq;
          plans.push(plan);
          progressed = true;
        }
      }
      if (!progressed) {
        break;
      }
    }
    return plans;
  }

  function release(token) {
    const lease = leases.get(token);
    if (lease === undefined || lease.legacy) {
      return false;
    }
    const now = clock();
    if (lease.expiresAt <= now) {
      return false;
    }
    purgeExpiredWaiters(now);

    // A freed resource goes to the requests at the head of its queue; group
    // requests only wake once every copy they need is free. All wakeup grants
    // ride along in the same write as the release, so a failed log leaves the
    // lease and every queue untouched.
    const plans = scheduleWakeupsAfterFreed([lease.resource], now);
    const events = [{ v: LOG_VERSION, type: 'release', at: now, token }];
    for (const plan of plans) {
      for (const grant of plan.grants) {
        events.push(grant.event);
      }
    }
    appendEvents(events);

    // The record comes off immediately; its queued node retires lazily.
    leases.delete(token);
    removeSlot(lease.resource, token);
    counters.released += 1;
    for (const plan of plans) {
      applyWakeup(plan);
    }
    return true;
  }

  // Simulate freeing the given resources, then collect every queued request
  // that becomes grantable as a result, cascading through the queues.
  function scheduleWakeupsAfterFreed(freedResources, now) {
    const plans = [];
    let seq = tokenSequence;
    // Virtual view: slots removed in this operation plus grants planned here.
    const virtualFreed = new Map();
    for (const resource of freedResources) {
      virtualFreed.set(resource, (virtualFreed.get(resource) ?? 0) + 1);
    }

    for (;;) {
      let progressed = false;
      for (const queue of waitQueues.values()) {
        const head = queue[0];
        if (head === undefined) {
          continue;
        }
        if (plans.some((plan) => plan.group === head.group)) {
          continue;
        }
        let fillable = true;
        for (const position of head.group.positions) {
          if (position.granted) {
            continue;
          }
          const resourceQueue = waitQueues.get(position.resource);
          if (resourceQueue === undefined) {
            fillable = false;
            break;
          }
          const earlier = resourceQueue.indexOf(position);
          let pendingAhead = 0;
          for (let i = 0; i < earlier; i += 1) {
            const ahead = resourceQueue[i];
            if (ahead.granted) {
              continue;
            }
            if (plans.some((plan) =>
              plan.grants.some((grant) => grant.position === ahead))) {
              continue;
            }
            pendingAhead += 1;
          }
          if (pendingAhead > 0) {
            fillable = false;
            break;
          }
          const plannedHere = countPlannedGrantsFor(plans, position.resource);
          const virtuallyFree = virtualFreed.get(position.resource) ?? 0;
          if (liveSlotCount(position.resource, now) + plannedHere
              > virtuallyFree) {
            fillable = false;
            break;
          }
        }
        if (!fillable) {
          continue;
        }
        const plan = planWakeup(head.resource, now, seq);
        if (plan !== null) {
          seq = plan.seq;
          plans.push(plan);
          // The grants consume free slots and may free nothing; balance the
          // virtual view accordingly per resource.
          for (const grant of plan.grants) {
            const left = (virtualFreed.get(grant.resource) ?? 0);
            if (left > 0) {
              virtualFreed.set(grant.resource, left - 1);
            }
          }
          progressed = true;
        }
      }
      if (!progressed) {
        break;
      }
    }
    return plans;
  }

  // Cancelling only lands on a request that is still queued: an already
  // woken, expired or cancelled request reports false, as does an unknown id.
  function cancel(requestId) {
    purgeExpiredWaiters(clock());
    const group = pendingGroups.get(requestId);
    if (group === undefined) {
      return false;
    }
    removeGroupFromQueues(group);
    pendingGroups.delete(requestId);
    group.ticket.status = 'cancelled';
    return true;
  }

  function sweep(now = clock()) {
    purgeExpiredWaiters(now);
    const due = [];
    while (expiryQueue.size > 0) {
      const node = expiryQueue.peek();
      if (node.expiresAt > now) {
        break;
      }
      expiryQueue.pop();
      const lease = leases.get(node.token);
      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
        // Retired node: release, retake or renewal already superseded it.
        continue;
      }
      due.push(node);
    }

    if (due.length === 0) {
      return [];
    }

    // Reclaimed resources are handed to the head requests of their queues in
    // the same expiry order the reclaim happens; every wakeup grant rides
    // along in the same log write, so a failed append rolls everything back.
    const reclaimable = [];
    for (const node of due) {
      const lease = leases.get(node.token);
      if (getSlots(lease.resource).includes(node.token)) {
        reclaimable.push(node);
      }
    }

    const events = [{
      v: LOG_VERSION,
      type: 'reclaim',
      at: now,
      items: reclaimable.map((node) => ({
        token: node.token,
        resource: leases.get(node.token).resource,
      })),
    }];
    const plans = scheduleWakeupsAfterFreed(
      reclaimable.map((node) => leases.get(node.token).resource),
      now,
    );
    for (const plan of plans) {
      for (const grant of plan.grants) {
        events.push(grant.event);
      }
    }

    try {
      appendEvents(events);
    } catch (error) {
      // The write never happened: put the popped nodes back so the queue is
      // byte-for-byte the same as before the call.
      for (const node of due) {
        expiryQueue.push(node);
      }
      throw error;
    }

    const freed = [];
    for (const node of reclaimable) {
      const lease = leases.get(node.token);
      leases.delete(node.token);
      if (removeSlot(lease.resource, node.token)) {
        counters.reclaimed += 1;
        freed.push(lease.resource);
      }
    }
    for (const plan of plans) {
      applyWakeup(plan);
    }
    return freed;
  }

  function holder(resource) {
    const now = clock();
    purgeExpiredWaiters(now);
    return liveHolder(resource, now);
  }

  function stats() {
    let live = 0;
    const now = clock();
    purgeExpiredWaiters(now);
    for (const list of slots.values()) {
      for (const token of list) {
        if (isLive(leases.get(token), now)) {
          live += 1;
        }
      }
    }
    return {
      granted: counters.granted,
      renewed: counters.renewed,
      released: counters.released,
      reclaimed: counters.reclaimed,
      live,
    };
  }

  replay();

  return {
    acquire,
    acquireGroup,
    renew,
    release,
    sweep,
    holder,
    stats,
    cancel,
  };

  function replay() {
    if (logPath === null) {
      return;
    }

    let text;
    try {
      text = fs.readFileSync(logPath, 'utf8');
    } catch (cause) {
      if (cause.code === 'ENOENT') {
        // No log yet: start from an empty registry.
        return;
      }
      throw new LogFileError(
        `failed to read lease log at ${logPath}`,
        cause,
      );
    }

    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i];
      if (line.trim() === '') {
        continue;
      }
      let event;
      try {
        event = JSON.parse(line);
      } catch (cause) {
        throw new LogFileError(
          `corrupt lease log entry on line ${i + 1} of ${logPath}`,
          cause,
        );
      }
      replayEvent(event, i + 1);
    }
  }

  function replayEvent(event, lineNumber) {
    if (event === null || typeof event !== 'object' || event.v !== LOG_VERSION) {
      throw new LogFileError(
        `unrecognized lease log version on line ${lineNumber} of ${logPath}`,
      );
    }

    switch (event.type) {
      case 'acquire': {
        if (
          typeof event.token !== 'string' ||
          !Number.isFinite(event.ttlMs) ||
          !Number.isFinite(event.expiresAt)
        ) {
          throw new LogFileError(
            `corrupt acquire entry on line ${lineNumber} of ${logPath}`,
          );
        }
        const lease = {
          resource: event.resource,
          holder: event.holder,
          expiresAt: event.expiresAt,
          ttlMs: event.ttlMs,
          // Credentials issued before this process started are void: the
          // lease keeps occupying the resource, but its token cannot
          // renew or release it.
          legacy: true,
          heapSeq: 0,
        };
        leases.set(event.token, lease);
        addSlot(event.resource, event.token);
        knownTokens.add(event.token);
        enqueue(event.token, lease);
        counters.granted += 1;
        break;
      }
      case 'renew': {
        const lease = leases.get(event.token);
        if (
          typeof event.token !== 'string' ||
          !Number.isFinite(event.expiresAt)
        ) {
          throw new LogFileError(
            `corrupt renew entry on line ${lineNumber} of ${logPath}`,
          );
        }
        if (lease !== undefined) {
          lease.expiresAt = event.expiresAt;
          lease.heapSeq += 1;
          enqueue(event.token, lease);
        }
        counters.renewed += 1;
        break;
      }
      case 'release': {
        if (typeof event.token !== 'string') {
          throw new LogFileError(
            `corrupt release entry on line ${lineNumber} of ${logPath}`,
          );
        }
        const lease = leases.get(event.token);
        if (lease !== undefined) {
          leases.delete(event.token);
          removeSlot(lease.resource, event.token);
        }
        counters.released += 1;
        break;
      }
      case 'reclaim': {
        if (!Array.isArray(event.items)) {
          throw new LogFileError(
            `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
          );
        }
        for (const item of event.items) {
          if (item === null || typeof item !== 'object' ||
              typeof item.token !== 'string') {
            throw new LogFileError(
              `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
            );
          }
          const token = item.token;
          const lease = leases.get(token);
          if (lease !== undefined) {
            leases.delete(token);
            removeSlot(lease.resource, token);
          }
          counters.reclaimed += 1;
        }
        break;
      }
      default: {
        throw new LogFileError(
          `unknown lease log event type on line ${lineNumber} of ${logPath}`,
        );
      }
    }
  }
}

