const GRANTED = 'granted';
const GIVE_UP = new Set(['timeout', 'expired', 'timedout', 'timed-out', 'abandoned']);
const CANCELLED = new Set(['cancelled', 'canceled']);

function clock(start = 0) {
  let now = start;
  const fn = () => now;
  fn.set = (value) => {
    now = value;
  };
  return fn;
}

function ticketId(res) {
  const id = res && (res.requestId ?? res.waitId ?? res.id);
  assert.equal(typeof id, 'string', 'queue result must carry a request id: ' + JSON.stringify(res));
  assert.ok(id.length > 0, 'the request id must not be empty');
  return id;
}

function statusOf(reg, res) {
  reg.stats();
  return res.status;
}

