  assert.equal(statusOf(reg, res), WAITING, label + ' should still be waiting: ' + JSON.stringify(res));
  assert.equal(res.token, undefined, label + ' must not carry a credential while waiting');
}

function assertGranted(reg, res, label) {
  assert.equal(statusOf(reg, res), GRANTED, label + ' should have been granted: ' + JSON.stringify(res));
  assert.equal(typeof res.token, 'string', label + ' must carry a credential once granted');
  assert.ok(res.token.length > 0, label + ' credential must not be empty');
  assert.equal(typeof res.expiresAt, 'number', label + ' must carry its own expiry');
}

function assertGiveUp(reg, res, label) {
  const status = statusOf(reg, res);
  assert.ok(GIVE_UP.has(status), label + ' should read as given up, got ' + String(status));
  assert.equal(res.token, undefined, label + ' must never be handed a credential');
}

