  assert.equal(reg.holder('x'), 'worker-3');
  assert.equal(reg.holder('y'), 'worker-4');
  assert.deepEqual(reg.stats(), { granted: 4, renewed: 0, released: 0, reclaimed: 2, live: 2 });
}

function testTimeoutGivesUpAndIsNeverWoken() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const lease = reg.acquire('slot-7', 'alpha', 100);
  const w1 = reg.acquire('slot-7', 'beta', 40, 20);
  const w2 = reg.acquire('slot-7', 'gamma', 40, 1000);
  const id1 = ticketId(w1);

  c.set(15);
  assertWaiting(reg, w1, 'w1');
  assertWaiting(reg, w2, 'w2');

