  assertCancelled(reg, w1, 'w1');
  assertGranted(reg, w2, 'w2');
  assert.equal(reg.holder('slot-9'), 'gamma');
  assert.deepEqual(reg.stats(), { granted: 2, renewed: 0, released: 1, reclaimed: 0, live: 1 });

  // an already woken request can no longer be cancelled
  assert.equal(reg.cancel(id2), false, 'an already woken request cannot be cancelled');
  assert.equal(reg.holder('slot-9'), 'gamma');
}

