  assertWaiting(reg, w3, 'w3');
  assert.equal(reg.holder('slot-3'), 'beta');

  assert.equal(reg.release(w1.token), true);
  assertGranted(reg, w2, 'w2');
  assertWaiting(reg, w3, 'w3');
  assert.equal(reg.holder('slot-3'), 'gamma');
}

function testRenewDuringWaitKeepsOrder() {
  const c = clock(0);
  const reg = createRegistry({ ttlMs: 100, clock: c });
  const lease = reg.acquire('slot-4', 'alpha', 40);
  const w = reg.acquire('slot-4', 'beta', 30, 1000);

  c.set(30);
