  reg.acquire('slot-5', 'alpha', 10);
  const w = reg.acquire('slot-5', 'beta', 30, 1000);

  c.set(15);
  assert.deepEqual(reg.sweep(), ['slot-5']);
  assertGranted(reg, w, 'w');
