743	      if (getSlots(lease.resource).includes(node.token)) {
744	        reclaimable.push(node);
745	      } else {
746	        leases.delete(node.token);
747	      }
748	    }
749	
750	    if (reclaimable.length === 0) {
751	      return [];
752	    }
753	
754	    // Reclaimed resources are handed to the head requests of their queues in
755	    // the same expiry order the reclaim happens; every wakeup grant rides
756	    // along in the same log write, so a failed append rolls everything back.
757	    const events = [{
758	      v: LOG_VERSION,
759	      type: 'reclaim',
760	      at: now,
761	      items: reclaimable.map((node) => ({
762	        token: node.token,
