787	    const freed = [];
788	    for (const node of reclaimable) {
789	      const lease = leases.get(node.token);
790	      leases.delete(node.token);
791	      if (removeSlot(lease.resource, node.token)) {
792	        counters.reclaimed += 1;
793	        freed.push(lease.resource);
794	      }
