820	      granted: counters.granted,
821	      renewed: counters.renewed,
822	      released: counters.released,
823	      reclaimed: counters.reclaimed,
824	      live,
825	    };
826	  }
827	
828	  replay();
829	
830	  return {
831	    acquire,
832	    acquireAll,
833	    acquireGroup: acquireAll,
834	    renew,
835	    release,
836	    sweep,
837	    holder,
838	    stats,
839	    cancel,
840	  };
841	
842	  function replay() {
843	    if (logPath === null) {
844	      return;
845	    }
846	
847	    let text;
848	    try {
849	      text = fs.readFileSync(logPath, 'utf8');
850	    } catch (cause) {
851	      if (cause.code === 'ENOENT') {
852	        // No log yet: start from an empty registry.
853	        return;
854	      }
855	      throw new LogFileError(
856	        `failed to read lease log at ${logPath}`,
857	        cause,
858	      );
859	    }
