899	          resource: event.resource,
900	          holder: event.holder,
901	          expiresAt: event.expiresAt,
902	          ttlMs: event.ttlMs,
903	          // Credentials issued before this process started are void: the
904	          // lease keeps occupying the resource, but its token cannot
905	          // renew or release it.
906	          legacy: true,
907	          heapSeq: 0,
908	        };
