      const group = head.group;
      if (plans.some((plan) => plan.group === group)) {
        continue;
      }
      if (!groupFillable(group, plans, freedResources)) {
        continue;
      }
      const plan = planGroupGrants(group, now, seq, batchId);
      seq = plan.seq;
      plans.push(plan);
      progressed = true;
    }
    if (!progressed) {
      break;
    }
  }
  return plans;
}

