import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRegistry, LeaseTakenError, LogFileError } from './src/index.js';

function fakeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (v) => { now = v; };
  clock.advance = (d) => { now += d; };
  return clock;
}

// 1. Atomic success: independent credentials and expiries.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const got = r.acquireAll(['a', 'b'], 'h', [40, 60]);
  assert.equal(got.length, 2);
  assert.equal(got[0].resource, 'a');
  assert.equal(got[1].resource, 'b');
  assert.notEqual(got[0].token, got[1].token);
  assert.equal(got[0].expiresAt, 40);
  assert.equal(got[1].expiresAt, 60);
  assert.deepEqual(r.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 0, live: 2 });
  console.log('1 ok');
}

// 2. One taken -> whole batch queues, holds nothing.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('a', 'x');
  const t = r.acquireAll(['a', 'b'], 'h', 50, 1000);
  assert.equal(t.status, 'waiting');
  assert.equal(r.holder('b'), null);
  assert.deepEqual(r.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  // no-wait on the batch throws LeaseTakenError with code, moves nothing
  assert.throws(() => r.acquireAll(['b', 'a'], 'y'), (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN' && e.resource === 'a');
  assert.equal(r.stats().granted, 1);
  console.log('2 ok');
}

// 3. Timeout abandons whole batch; positions gone; then resources grantable.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'x');
  const t = r.acquireAll(['a', 'b'], 'h', 50, 5);
  clock.set(5);
  r.stats(); // observe deadline
  assert.equal(t.status, 'expired');
  assert.equal(r.release(a.token), true);
  assert.equal(t.status, 'expired');
  assert.equal(r.holder('a'), null);
  assert.equal(r.holder('b'), null);
  assert.deepEqual(r.stats(), { granted: 1, renewed: 0, released: 1, reclaimed: 0, live: 0 });
  const got = r.acquireAll(['a', 'b'], 'z', 10);
  assert.equal(got.length, 2);
  assert.equal(r.stats().granted, 3);
  console.log('3 ok');
}

// 4. Wake only when the whole batch is fillable; FIFO with a single in between.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h1');
  const b = r.acquire('b', 'h2');
  const g1 = r.acquireAll(['a', 'b'], 'G', [10, 20], 1000); // arrives first
  const s2 = r.acquire('a', 'S', 30, 1000);                  // arrives second, on a
  assert.equal(g1.status, 'waiting');
  assert.equal(s2.status, 'waiting');

  clock.set(10);
  // Freeing only b: g1 still needs a; nobody can take b? A later waiter on b
  // could, but there is none. Nothing wakes.
  assert.equal(r.release(b.token), true);
  assert.equal(g1.status, 'waiting');
  assert.equal(s2.status, 'waiting');
  assert.equal(r.holder('b'), null);

  // Freeing a: g1's positions are at the head of both queues, so it wakes as
  // a whole; s2 stays queued.
  assert.equal(r.release(a.token), true);
  assert.equal(g1.status, 'granted');
  assert.equal(g1.leases.length, 2);
  assert.deepEqual(g1.leases.map((l) => l.resource), ['a', 'b']);
  assert.equal(g1.leases[0].expiresAt, 20); // 10 + 10
  assert.equal(g1.leases[1].expiresAt, 30); // 10 + 20
  assert.equal(s2.status, 'waiting');
  assert.equal(r.holder('a'), 'G');
  assert.equal(r.holder('b'), 'G');
  assert.deepEqual(r.stats(), { granted: 4, renewed: 0, released: 2, reclaimed: 0, live: 2 });
  console.log('4 ok');
}

// 5. Strict FIFO: single waiting ahead of group on 'a' gets served first.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h1');
  r.acquire('b', 'h2');
  const s1 = r.acquire('a', 'S', 30, 1000);
  const g1 = r.acquireAll(['a', 'b'], 'G', 30, 1000);
  clock.set(10);
  assert.equal(r.release(a.token), true);
  assert.equal(s1.status, 'granted');
  assert.equal(g1.status, 'waiting');
  assert.equal(r.holder('a'), 'S');
  console.log('5 ok');
}

// 6. Duplicate resource listed twice: two credentials, two releases to vacate.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const got = r.acquireAll(['x', 'x'], 'h', 40);
  assert.equal(got.length, 2);
  assert.notEqual(got[0].token, got[1].token);
  assert.deepEqual(r.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 0, live: 2 });
  // A concurrent single applicant loses.
  assert.throws(() => r.acquire('x', 'other'), LeaseTakenError);
  // A waiting group for [x,x] must wait until BOTH credentials are gone.
  const t = r.acquireAll(['x', 'x'], 'g', 10, 1000);
  clock.set(10);
  assert.equal(r.release(got[0].token), true);
  assert.equal(t.status, 'waiting');
  assert.equal(r.release(got[1].token), true);
  assert.equal(t.status, 'granted');
  assert.equal(t.leases.length, 2);
  assert.notEqual(t.leases[0].token, t.leases[1].token);
  assert.equal(r.stats().granted, 4);
  console.log('6 ok');
}

// 7. Cancel abandons the whole batch exactly once.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('a', 'x');
  const t = r.acquireAll(['a', 'b'], 'h', 50, 1000);
  assert.equal(r.cancel(t.waitId), true);
  assert.equal(t.status, 'cancelled');
  assert.equal(r.cancel(t.waitId), false);
  assert.equal(r.stats().granted, 1);
  console.log('7 ok');
}

// 8. Failed log write rolls the whole batch back.
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-group-'));
  const p = path.join(dir, 'g.log');
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock, logPath: p });
  r.acquire('x', 'h');
  fs.renameSync(p, p + '.bak');
  fs.mkdirSync(p);
  try {
    assert.throws(() => r.acquireAll(['a', 'b'], 'h'), (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR');
  } finally {
    fs.rmdirSync(p);
    fs.renameSync(p + '.bak', p);
  }
  assert.equal(r.holder('a'), null);
  assert.equal(r.holder('b'), null);
  assert.equal(r.stats().granted, 1);
  const got = r.acquireAll(['a', 'b'], 'h');
  assert.equal(got.length, 2);
  assert.equal(r.stats().granted, 3);
  fs.rmSync(dir, { recursive: true, force: true });
  console.log('8 ok');
}

// 9. Woken group batch is persisted and replays as ordinary leases.
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-group-'));
  const p = path.join(dir, 'g.log');
  const clock = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock, logPath: p });
  const a = r.acquire('a', 'h1');
  const b = r.acquire('b', 'h2');
  const g = r.acquireAll(['a', 'b'], 'G', [40, 60], 1000);
  clock.set(10);
  r.release(a.token);
  assert.equal(g.status, 'waiting');
  r.release(b.token);
  assert.equal(g.status, 'granted');
  assert.deepEqual(r.stats(), { granted: 4, renewed: 0, released: 2, reclaimed: 0, live: 2 });

  r = createRegistry({ ttlMs: 100, clock: fakeClock(10), logPath: p });
  assert.equal(r.holder('a'), 'G');
  assert.equal(r.holder('b'), 'G');
  assert.deepEqual(r.stats(), { granted: 4, renewed: 0, released: 2, reclaimed: 0, live: 2 });
  for (const l of g.leases) assert.equal(r.release(l.token), false);
  assert.deepEqual(r.sweep(49), []);
  assert.deepEqual(r.sweep(50), ['a']);
  assert.deepEqual(r.sweep(70), ['b']);
  fs.rmSync(dir, { recursive: true, force: true });
  console.log('9 ok');
}

// 10. Sweep waking a group; per-resource FIFO across sweep cascades.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('a', 'h1', 10);
  r.acquire('b', 'h2', 20);
  const g = r.acquireAll(['a', 'b'], 'G', 50, 1000);
  clock.set(15);
  assert.deepEqual(r.sweep(), ['a']);
  assert.equal(g.status, 'waiting');
  clock.set(25);
  assert.deepEqual(r.sweep(), ['b']);
  assert.equal(g.status, 'granted');
  assert.equal(g.leases[0].expiresAt, 75);
  assert.equal(g.leases[1].expiresAt, 75);
  console.log('10 ok');
}

// 11. array overload on acquire
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const got = r.acquire(['a', 'b'], 'h', 10);
  assert.equal(got.length, 2);
  assert.equal(r.stats().granted, 2);
  console.log('11 ok');
}

// 12. Failed append on waking group rolls queues and counters back.
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-group-'));
  const p = path.join(dir, 'g.log');
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock, logPath: p });
  const a = r.acquire('a', 'h1');
  r.acquire('b', 'h2');
  const g = r.acquireAll(['a', 'b'], 'G', 50, 1000);
  fs.renameSync(p, p + '.bak');
  fs.mkdirSync(p);
  try {
    assert.throws(() => r.release(a.token), (e) => e instanceof LogFileError);
  } finally {
    fs.rmdirSync(p);
    fs.renameSync(p + '.bak', p);
  }
  assert.equal(g.status, 'waiting');
  assert.equal(r.holder('a'), 'h1');
  assert.equal(r.stats().granted, 2);
  assert.equal(r.stats().released, 0);
  fs.rmSync(dir, { recursive: true, force: true });
  console.log('12 ok');
}

// 13. Group that queues on a resource with a single waiter behind: when
// resources free, earlier group takes all; later single still waits.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h1');
  const b = r.acquire('b', 'h2');
  const g = r.acquireAll(['a', 'b'], 'G', 30, 1000);
  const s = r.acquire('a', 'S', 30, 1000);
  clock.set(10);
  r.release(a.token);
  r.release(b.token);
  assert.equal(g.status, 'granted');
  assert.equal(s.status, 'waiting');
  assert.equal(r.holder('a'), 'G');
  assert.equal(r.holder('b'), 'G');
  // release G's a credential -> goes to S
  const ga = g.leases.find((l) => l.resource === 'a');
  r.release(ga.token);
  assert.equal(s.status, 'granted');
  assert.equal(r.holder('a'), 'S');
  console.log('13 ok');
}

// 14. Clock backwards: judged as given.
{
  const clock = fakeClock(100);
  const r = createRegistry({ ttlMs: 100, clock });
  const l = r.acquire('a', 'h', 50); // expires 150
  clock.set(120);
  assert.equal(r.stats().live, 1);
  clock.set(90); // backwards: still live
  assert.equal(r.stats().live, 1);
  assert.equal(r.renew(l.token), true);
  console.log('14 ok');
}

// 15. Expiry instant semantics: expiresAt == now not live; reclaimed only on sweep.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquireAll(['a'], 'h', 10);
  clock.set(10);
  assert.equal(r.stats().live, 0);
  assert.equal(r.stats().reclaimed, 0);
  assert.deepEqual(r.sweep(), ['a']);
  assert.equal(r.stats().reclaimed, 1);
  console.log('15 ok');
}

console.log('ALL SCRATCH CHECKS PASSED');

