import assert from 'node:assert/strict';
import { createRegistry } from './src/index.js';

function fakeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (v) => { now = v; };
  return clock;
}

// A. One sweep frees every resource a group needs: the group wakes in that sweep.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('a', 'h1', 10);
  r.acquire('b', 'h2', 20);
  const g = r.acquireAll(['a', 'b'], 'G', 50, 1000);
  clock.set(25);
  assert.deepEqual(r.sweep(), ['a', 'b']);
  assert.equal(g.status, 'granted');
  assert.equal(g.leases[0].expiresAt, 75);
  assert.equal(g.leases[1].expiresAt, 75);
  assert.deepEqual(r.stats(), { granted: 4, renewed: 0, released: 0, reclaimed: 2, live: 2 });
  console.log('A ok');
}

// B. Two independent groups made ready by one sweep both wake, arrival order.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('a', 'h1', 10);
  r.acquire('b', 'h2', 10);
  r.acquire('c', 'h3', 10);
  r.acquire('d', 'h4', 10);
  const g1 = r.acquireAll(['a', 'b'], 'G1', 30, 1000);
  const g2 = r.acquireAll(['c', 'd'], 'G2', 40, 1000);
  clock.set(15);
  const freed = r.sweep();
  assert.deepEqual(freed.sort(), ['a', 'b', 'c', 'd']);
  assert.equal(g1.status, 'granted');
  assert.equal(g2.status, 'granted');
  assert.equal(g1.leases[0].expiresAt, 45);
  assert.equal(g2.leases[0].expiresAt, 55);
  assert.equal(r.stats().granted, 8);
  assert.equal(r.stats().reclaimed, 4);
  console.log('B ok');
}

// C. Timed-out group unblocks a later single waiter on the same resource.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h1');
  const g = r.acquireAll(['a', 'b'], 'G', 30, 5);
  const s = r.acquire('a', 'S', 30, 1000);
  clock.set(6);
  r.stats(); // observe g's deadline
  assert.equal(g.status, 'expired');
  assert.equal(s.status, 'waiting');
  r.release(a.token);
  assert.equal(s.status, 'granted');
  assert.equal(r.holder('a'), 'S');
  assert.equal(r.stats().granted, 2);
  console.log('C ok');
}

// D. Duplicate holder: one credential expires while its twin is renewed; a
// later waiter only gets in once the twin is released.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const got = r.acquireAll(['x', 'x'], 'h', [10, 100]);
  const s = r.acquire('x', 'S', 30, 1000);
  clock.set(15);
  assert.deepEqual(r.sweep(), ['x']); // only the short credential is reclaimed
  assert.equal(s.status, 'waiting');   // the twin still holds x
  assert.equal(r.stats().reclaimed, 1);
  assert.equal(r.stats().granted, 2);
  assert.equal(r.renew(got[1].token), true);
  r.release(got[1].token);
  assert.equal(s.status, 'granted');
  assert.equal(r.holder('x'), 'S');
  console.log('D ok');
}

// E. Direct group grant with a wait budget when everything is free still
// returns credentials immediately (array, not a waiting ticket).
{
  const r = createRegistry({ ttlMs: 100, clock: fakeClock(0) });
  const got = r.acquireAll(['a', 'b'], 'h', 10, 1000);
  assert.equal(Array.isArray(got), true);
  assert.equal(got.length, 2);
  assert.equal(r.stats().granted, 2);
  console.log('E ok');
}

// F. Per-position credentials renew independently.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const got = r.acquireAll(['a', 'b'], 'h', [10, 100]);
  clock.set(8);
  assert.equal(r.renew(got[0].token), true);
  clock.set(15);
  assert.equal(r.stats().live, 1); // b only
  assert.deepEqual(r.sweep(), []); // a's renewed expiry is 18
  clock.set(18);
  assert.deepEqual(r.sweep(), ['a']);
  assert.equal(r.stats().reclaimed, 1);
  console.log('F ok');
}

// G. Mixed queue: group then single then group on overlapping resources;
// freeing must honor each resource's own FIFO.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h0');
  const b = r.acquire('b', 'h0');
  const g1 = r.acquireAll(['a', 'b'], 'G1', 20, 1000);
  const s1 = r.acquire('a', 'S1', 20, 1000);
  const g2 = r.acquireAll(['a', 'b'], 'G2', 20, 1000);
  clock.set(10);
  r.release(a.token);
  r.release(b.token);
  // g1 is the only head request; it takes both.
  assert.equal(g1.status, 'granted');
  assert.equal(s1.status, 'waiting');
  assert.equal(g2.status, 'waiting');
  // g1 frees a -> s1 (a head), but s1 needs nothing else: granted.
  r.release(g1.leases[0].token);
  assert.equal(s1.status, 'granted');
  assert.equal(g2.status, 'waiting'); // still blocked on a (s1) and b
  r.release(g1.leases[1].token);
  assert.equal(g2.status, 'waiting'); // blocked by s1 on a
  r.release(s1.token);
  assert.equal(g2.status, 'granted');
  assert.deepEqual(g2.leases.map((l) => l.resource), ['a', 'b']);
  console.log('G ok');
}

// H. Group waits behind a single; once single gets served and later frees,
// the group is woken even though it queued while the resource was busy.
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  const a = r.acquire('a', 'h0');
  r.acquire('b', 'hb');
  const s1 = r.acquire('a', 'S1', 20, 1000);
  const g1 = r.acquireAll(['a', 'b'], 'G1', 20, 1000);
  clock.set(10);
  r.release(a.token);
  assert.equal(s1.status, 'granted');
  assert.equal(g1.status, 'waiting');
  r.release(s1.token);
  assert.equal(g1.status, 'waiting'); // b still held
  console.log('H ok (partial; b release needed)');
}

console.log('ALL EXTRA CHECKS PASSED');

