// A queued request is fillable exactly when every position reaches the
// front of its resource's queue and that resource is free once the
// triggering event is applied. Occupancy is boolean per resource: held
// means at least one credential is still present; a request listing one
// resource twice waits until the holder released every copy it held.
function groupFillable(group, plans, freedCount) {
  for (const position of group.positions) {
    if (position.granted) {
      continue;
    }
    const queue = waitQueues.get(position.resource);
    if (queue === undefined) {
      return false;
    }
    const index = queue.indexOf(position);
    for (let i = 0; i < index; i += 1) {
      const ahead = queue[i];
      if (ahead.group === group) {
        // Own repeated listing: its positions are granted together.
        continue;
      }
      if (positionPlanned(plans, ahead)) {
        continue;
      }
      return false;
    }
    // Occupancy after the triggering free: slots are read while the freed
    // credentials are still present; resources the event does not touch
    // keep every slot they had.
    let occupied = Math.max(
      0,
      totalSlotCount(position.resource)
        - (freedCount.get(position.resource) ?? 0),
    );
    for (const plan of plans) {
      if (plan.group === group) {
        continue;
      }
      for (const grant of plan.grants) {
        if (grant.resource === position.resource) {
          occupied += 1;
        }
      }
    }
    if (occupied > 0) {
      return false;
    }
  }
  return true;
}

// Grant every queued request whose resources become available through the
// given freeing event, cascading across resources and queues. Everything
// planned here rides in the triggering log write.
function planWakeups(freedList, now) {
  const freedCount = new Map();
  for (const resource of freedList) {
    freedCount.set(resource, (freedCount.get(resource) ?? 0) + 1);
  }
  const plans = [];
  let seq = tokenSequence;
  for (;;) {
    // Candidates are picked strictly by arrival order: the earliest
    // pending request whose batch is now complete wins, so no resource's
    // queue can jump ahead of an earlier request.
    let next = null;
    for (const group of pendingGroups.values()) {
      if (plans.some((plan) => plan.group === group)) {
        continue;
      }
      if (!groupFillable(group, plans, freedCount)) {
        continue;
      }
      if (next === null || group.arrival < next.arrival) {
        next = group;
      }
    }
    if (next === null) {
      break;
    }
    const plan = planGroupGrants(next, now, seq);
    seq = plan.seq;
    plans.push(plan);
  }
  return plans;
}

